67	  return true;
68	}
69	/* Độ lấn của thân xe vào vật cản sol (m, ≤ 0 là không chồng): hộp lấy độ chồng nhỏ nhất trên 4 trục tách (SAT);
70	   tròn lấy r − khoảng cách từ tâm tròn tới thân xe (tâm tròn nằm trong thân xe thì r + khoảng tới cạnh gần nhất). Chỉ dùng cho đường thoát */
71	function drPenSolid(sol: DrSolid, x: number, z: number, c: number, s: number): number {
72	  const ac = Math.abs(c), as = Math.abs(s);
73	  if (sol.kind === 'circle') {
74	    const dx = sol.cx - x, dz = sol.cz - z, lf = dx * c - dz * s, ln = dx * s + dz * c;
75	    const ef = Math.abs(lf) - HL, en = Math.abs(ln) - HW;
76	    if (ef <= 0 && en <= 0) return sol.r - Math.max(ef, en);
77	    const qf = ef > 0 ? ef : 0, qn = en > 0 ? en : 0;
78	    return sol.r - Math.hypot(qf, qn);
79	  }
80	  const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
81	  return Math.min(ex + HL * ac + HW * as - Math.abs(dx), ez + HL * as + HW * ac - Math.abs(dz),
82	    HL + ex * ac + ez * as - Math.abs(dx * c - dz * s), HW + ex * as + ez * ac - Math.abs(dx * s + dz * c));
83	}
84	/* Thân xe chồng hộp xe tự động b không (cùng tầng: chân hai xe chênh < chiều cao xe) */
85	function drHitBox(b: DrBox, x: number, y: number, z: number, c: number, s: number): boolean {
86	  if (Math.abs(b.y - y) >= CAR.height) return false;
87	  const bc = Math.cos(b.yaw), bs = Math.sin(b.yaw), dx = b.x - x, dz = b.z - z;
88	  /* bốn trục tách: f1 = (c, −s), n1 = (s, c), f2 = (bc, −bs), n2 = (bs, bc); hình chiếu nửa hộp lên trục a là hl|f·a| + hw|n·a| */
89	  const ff = c * bc + s * bs, fn = c * bs - s * bc;                  // f1·f2, f1·n2
90	  const nf = s * bc - c * bs, nn = s * bs + c * bc;                  // n1·f2, n1·n2
91	  if (Math.abs(dx * c - dz * s) >= HL + b.hl * Math.abs(ff) + b.hw * Math.abs(fn) - EPS) return false;
92	  if (Math.abs(dx * s + dz * c) >= HW + b.hl * Math.abs(nf) + b.hw * Math.abs(nn) - EPS) return false;
93	  if (Math.abs(dx * bc - dz * bs) >= b.hl + HL * Math.abs(ff) + HW * Math.abs(nf) - EPS) return false;
94	  if (Math.abs(dx * bs + dz * bc) >= b.hw + HL * Math.abs(fn) + HW * Math.abs(nn) - EPS) return false;
95	  return true;
96	}
