219	/* ===== Đoạn thẳng (camera) ===== */
220	/* Tham số t ∈ [0, 1] nơi đoạn a + t·d đi vào vật cản o (khối hộp / trụ đứng giữa y0..y1); 1 nếu không cắt; 0 nếu a ở trong */
221	function drSegHit(o: DrSolid, ax: number, ay: number, az: number, dx: number, dy: number, dz: number): number {
222	  let t0 = -Infinity, t1 = Infinity;
223	  if (Math.abs(dy) < EPS) { if (ay < o.y0 || ay > o.y1) return 1; }
224	  else { const a = (o.y0 - ay) / dy, b = (o.y1 - ay) / dy; t0 = a < b ? a : b; t1 = a < b ? b : a; }
225	  if (o.kind === 'circle') {
226	    const ox = ax - o.cx, oz = az - o.cz, A = dx * dx + dz * dz, B = 2 * (ox * dx + oz * dz), C = ox * ox + oz * oz - o.r * o.r;
227	    if (A < EPS) { if (C > 0) return 1; }
228	    else {
229	      const D = B * B - 4 * A * C;
230	      if (D < 0) return 1;
231	      const q = Math.sqrt(D), a = (-B - q) / (2 * A), b = (-B + q) / (2 * A);
232	      if (a > t0) t0 = a; if (b < t1) t1 = b;
233	    }
234	  } else {
235	    if (Math.abs(dx) < EPS) { if (ax < o.x0 || ax > o.x1) return 1; }
236	    else { const a = (o.x0 - ax) / dx, b = (o.x1 - ax) / dx; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
237	    if (Math.abs(dz) < EPS) { if (az < o.z0 || az > o.z1) return 1; }
238	    else { const a = (o.z0 - az) / dz, b = (o.z1 - az) / dz; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
239	  }
240	  if (t0 > t1 || t1 < 0 || t0 > 1) return 1;
241	  return t0 > 0 ? t0 : 0;
242	}
