244	/* Phần đoạn thẳng a → b (0..1) đi được trước khi chạm vật cản (cùng khoảng cao độ, vì vật cản có y0..y1 tuyệt đối) */
245	export function drSegClear(net: DrNet, ax: number, ay: number, az: number, bx: number, by: number, bz: number): number {
246	  const g = drGrid(net), sol = net.solids, dx = bx - ax, dy = by - ay, dz = bz - az;
247	  let t = 1;
248	  const big = g.big;
249	  for (let i = 0; i < big.length; i++) { const h = drSegHit(sol[big[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
250	  const ix0 = Math.floor(Math.min(ax, bx) / DRC), ix1 = Math.floor(Math.max(ax, bx) / DRC);
251	  const iz0 = Math.floor(Math.min(az, bz) / DRC), iz1 = Math.floor(Math.max(az, bz) / DRC);
252	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
253	    const list = g.cells.get(drKey(ix, iz));
254	    if (!list) continue;
255	    for (let i = 0; i < list.length; i++) { const h = drSegHit(sol[list[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
256	  }
257	  return t;
258	}
259	/* ============================ Lái xe: chuyển động theo số liệu VF 3 ============================
260	   Mô hình "xe đạp" động học trên mặt bằng (spec §5.2): vị trí, hướng, tốc độ dọc có dấu, góc lái; không mô phỏng lốp, treo, trượt.
261	   - Tăng tốc: a = a0 không đổi tới 50 km/h (a0 = 50 km/h / t50, qua đúng mốc thứ nhất), sau đó a = a0 · v50 / v · (1 − u^k)
262	     với u = (v − v50) / (vMax − v50): giảm theo công suất không đổi và về 0 tại vMax. Số mũ k giải một lần (chia đôi) sao cho tới
263	     99 % vMax (27,5 m/s ≈ 100 km/h, vì đường cong chỉ tiệm cận vMax) đúng t100.
264	   - Lái: góc lái lớn nhất asin(wheelbase / turnRadius) (bán kính quay vòng tính ở tâm trục trước); tốc độ cao thì giới hạn thêm
265	     sao cho gia tốc ngang v² · tan(góc) / wheelbase ≤ latMax. Góc lái tiến về đích theo steerRate, tự trả về 0 theo steerReturn
266	     (cả hai là phần góc lái lớn nhất mỗi giây).
267	   - Phanh / lùi: phanh khi đang tiến; |v| < sim.revV mà giữ phanh, không ga thì lùi dần tới reverseMax; đang lùi mà đạp ga thì phanh
268	     về 0 rồi mới tiến. Nhả hết thì chậm dần theo coast, không tự lùi. Phanh tay hãm handBrake, không trượt. Dốc không đổi gia tốc.
269	   - drStep chia dt thành bước ≤ sim.dt (tối đa sim.steps bước, phần dư bỏ); mỗi bước dời thân xe bằng drMove (collide.ts);
270	     bị chặn thì mất phần tốc độ hướng vào vật cản một lần (đâm thẳng thì đứng hẳn, cọ chéo còn phần chiếu dọc vật cản),
271	     đang cọ thì hãm thêm perf.scrape (m/s²); kết quả không phụ thuộc tần số khung.
272	   Không cấp phát mỗi khung (D-018). Không import three. */
273	import { CONFIG } from '../../config';
274	import { drGround, type DrNet } from './net';
275	import { drSpawnPose } from './roadData';
276	import { drMove, type DrPose, type DrBox } from './collide';
277	
278	export interface DrState extends DrPose { pitch: number; v: number; steer: number; wheel: number; braking: boolean; evac: number; slide?: number; touch?: number }   // v: m/s có dấu; steer: rad; wheel: góc quay bánh tích lũy (rad); slide: phần tốc độ còn giữ trong lần chạm vật cản hiện tại (1 = không chạm, mặc định); touch: s còn coi là đang chạm (mặc định 0)
279	export interface DrInput { gas: number; brake: number; steer: number; hand: boolean }   // gas, brake: 0..1; steer: −1..1
280	
281	const CAR = CONFIG.drive.car, P = CONFIG.drive.perf, SIM = CONFIG.drive.sim;
282	const L = CAR.wheelbase;
283	const V50 = 50 / 3.6;                                                // m/s — mốc 0–50 km/h của t50
284	const STEER_GEOM = Math.asin(L / P.turnRadius);                     // rad — góc lái lớn nhất theo hình học
285	
286	/* ===== Đường cong tăng tốc ===== */
287	let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
288	function drAccelK(v: number, k: number): number {
289	  if (v <= V50) return A0;
290	  if (v >= P.vMax) return 0;
291	  const u = (v - V50) / (P.vMax - V50);
292	  return A0 * V50 / v * (1 - Math.pow(u, k));
293	}
294	/* Thời gian 0 → 0,99 vMax với số mũ k (tích phân dv / a, điểm giữa) */
295	function drT100(k: number): number {
296	  const vt = 0.99 * P.vMax, N = 2000, h = (vt - V50) / N;
297	  let t = V50 / A0;
298	  for (let i = 0; i < N; i++) t += h / drAccelK(V50 + (i + 0.5) * h, k);
299	  return t;
300	}
301	function drFitAccel(): void {
302	  A0 = V50 / P.t50;
303	  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: drT100 giảm theo k
304	  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (drT100(m) > P.t100) lo = m; else hi = m; }
305	  KEXP = (lo + hi) / 2;
306	}
307	/* m/s² khi đạp hết ga ở tốc độ v ≥ 0 */
308	export function drAccel(v: number): number {
309	  if (Number.isNaN(KEXP)) drFitAccel();
310	  return drAccelK(v, KEXP);
311	}
312	
313	/* rad — góc lái lớn nhất ở tốc độ v (dấu bỏ qua) */
314	export function drSteerMax(v: number): number {
315	  const a = Math.abs(v);
316	  if (a < 1e-6) return STEER_GEOM;
317	  const lim = Math.atan(L * P.latMax / (a * a));
318	  return lim < STEER_GEOM ? lim : STEER_GEOM;
319	}
320	
321	const drToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);
322	
323	/* Dốc dọc từ cao độ mặt đường tại trục trước / sau; giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
324	function drPitch(s: DrState, net: DrNet): void {
325	  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
326	  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
327	  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
328	}
