330	/* Xe mới ở chỗ xuất phát của slot, đứng yên trên mặt đường cao nhất tại đó (mặt cầu) */
331	export function drCreate(net: DrNet, slot: number): DrState {
332	  const sp = drSpawnPose(slot);
333	  let y = -Infinity;
334	  for (const p of net.pads) {
335	    if (sp.x < p.x0 || sp.x > p.x1 || sp.z < p.z0 || sp.z > p.z1) continue;
336	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
337	    y = Math.max(y, p.y(sp.x, sp.z));
338	  }
339	  const s: DrState = { x: sp.x, y: Number.isFinite(y) ? y : CONFIG.roadY, z: sp.z, yaw: sp.yaw, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0, slide: 1, touch: 0 };
340	  drPitch(s, net);
341	  return s;
342	}
343	
344	const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
345	
346	/* Một bước h ≤ sim.dt */
347	function drStep1(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
348	  const g = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, b = inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
349	  let v = s.v, braking = false;
350	  /* tốc độ */
351	  if (inp.hand) { v = drToward0(v, P.handBrake * h); braking = true; }
352	  else if (b > 0 && g === 0) {
353	    if (v >= SIM.revV) { v = Math.max(0, v - b * P.brake * h); braking = true; }                       // đang tiến: phanh
354	    else v = Math.max(-P.reverseMax, v - b * (v > 0 ? P.brake : drAccel(-v)) * h);                   // gần đứng / đang lùi: lùi dần
355	  } else if (g > 0 && b === 0) {
356	    if (v < 0) { v = Math.min(0, v + g * P.brake * h); braking = true; }                             // đang lùi: phanh về 0 rồi mới tiến
357	    else v = Math.min(P.vMax, v + g * drAccel(v) * h);
358	  } else if (g > 0 && b > 0) { v = drToward0(v, b * P.brake * h); braking = true; }
359	  else v = drToward0(v, P.coast * h);
360	  /* góc lái */
361	  const lim = drSteerMax(v), want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer;
362	  let st = s.steer;
363	  if (want === 0) st = drToward0(st, P.steerReturn * STEER_GEOM * h);
364	  else {
365	    const tgt = want * lim, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
366	    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_GEOM * h;
367	    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
368	  }
369	  if (st > lim) st = lim; else if (st < -lim) st = -lim;
370	  /* dời thân xe */
371	  const dist = v * h, f = drMove(net, s, dist, dist * Math.tan(st) / L, boxes, nBoxes, MOVED);
372	  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
373	  /* va chạm: phần quãng f là cos² góc giữa hướng trượt và hướng xe, nên √f là phần tốc độ chiếu theo hướng trượt.
374	     Chỉ mất phần hướng vào vật cản khi √f xuống dưới mức nhỏ nhất đã mất trong lần chạm này (slide), không lặp lại mỗi bước
375	     khi vẫn tì vào; đang cọ thì hãm thêm perf.scrape; không bị chặn quá sim.touch giây thì coi như đã rời vật cản. */
376	  let slide = s.slide ?? 1, touch = s.touch ?? 0;
377	  if (f < 1) {
378	    if (touch > 0) v = drToward0(v, P.scrape * h);                   // đang cọ: hãm thêm
379	    const q = f > 0 ? Math.sqrt(f) : 0;
380	    if (q === 0) v = 0;                                              // đứng hẳn: đâm thẳng, hoặc tì thẳng vào mà vẫn đạp ga
381	    else if (q < slide) v *= q / slide;
382	    if (q < slide) slide = q;
383	    touch = SIM.touch;
384	  } else if (touch > 0) { touch -= h; if (touch <= 0) { touch = 0; slide = 1; } }
385	  s.slide = slide; s.touch = touch;
386	  s.v = v; s.steer = st; s.braking = braking;
387	  s.wheel += dist * f / (CAR.wheelDia / 2);
388	  drPitch(s, net);
389	}
