391	/* Bước mô phỏng cho khung dài dt (s) */
392	export function drStep(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
393	  let rem = dt;
394	  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
395	    const h = rem < SIM.dt ? rem : SIM.dt;
396	    drStep1(s, inp, net, boxes, nBoxes, h);
397	    rem -= h;
398	  }
399	}
