544	/* onExit: thoát chung (explore.exit); Task 11 dùng khi mất kết nối lúc đang xem, lái một mình chưa cần */
545	export function setupDrive(c: SwingController, onExit: () => void): void {
546	  ctrl = c;
547	  window.addEventListener('keydown', (e) => {
548	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
549	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
550	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
551	    if (!DR_KEYS.has(e.code)) return;
552	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
553	    drKeys.add(e.code);
554	  });
555	  window.addEventListener('keyup', (e) => {
556	    drKeys.delete(e.code);
557	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
558	  });
559	  const drop = drBindDrop(window, document, drKeys);
560	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
561	  /* Kéo chuột trái trên canvas: xoay camera quanh xe (cảm ứng ở Task 9) */
