563	  canvas.addEventListener('pointerdown', (e) => {
564	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
565	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
566	    canvas.setPointerCapture(e.pointerId);
567	  });
568	  canvas.addEventListener('pointermove', (e) => {
569	    if (e.pointerId !== dragId) return;
570	    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
571	    lx = e.clientX; ly = e.clientY;
572	  });
573	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
574	  canvas.addEventListener('pointerup', end);
575	  canvas.addEventListener('pointercancel', end);
576	  canvas.addEventListener('lostpointercapture', end);
577	}
