593	/* net.solids chỉ được thêm bằng push (chỉ mục lưới của collide.ts dựa vào điều đó); barie Cầu sông Hàn chặn bằng cổng của ô, không thêm / xóa vật cản */
594	export function drAddSolids(net: DrNet, more: DrSolid[]): void {
