601	
602	/* Chỉ số ô chứa (x, z) có cao độ gần yRef nhất trong ± stepMax; −1 nếu không có. Duyệt tuyến tính, không cấp phát */
603	function drPadAt(net: DrNet, x: number, z: number, yRef: number): number {
604	  const pads = net.pads, step = CONFIG.drive.stepMax;
605	  let best = -1, bestD = Infinity;
606	  for (let i = 0; i < pads.length; i++) {
607	    const p = pads[i];
608	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
609	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
610	    const d = Math.abs(p.y(x, z) - yRef);
611	    if (d <= step && d < bestD) { best = i; bestD = d; }
612	  }
613	  return best;
614	}
615	/* Cao độ mặt đường tại (x, z) ở tầng gần yRef nhất; NaN nếu không có ô nào cùng tầng */
616	export function drGround(net: DrNet, x: number, z: number, yRef: number): number {
617	  const i = drPadAt(net, x, z, yRef);
618	  return i < 0 ? NaN : net.pads[i].y(x, z);
619	}
620	
621	/* Khung bao mặt bằng và cao độ của mọi ô (cao độ lấy mẫu mỗi ≤ 2 m theo hai trục) */
622	export function drBounds(net: DrNet): { x0: number; x1: number; z0: number; z1: number; yMin: number; yMax: number } {
623	  const b = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity, yMin: Infinity, yMax: -Infinity };
624	  for (const p of net.pads) {
625	    b.x0 = Math.min(b.x0, p.x0); b.x1 = Math.max(b.x1, p.x1); b.z0 = Math.min(b.z0, p.z0); b.z1 = Math.max(b.z1, p.z1);
626	    const nx = Math.ceil((p.x1 - p.x0) / 2), nz = Math.ceil((p.z1 - p.z0) / 2);
627	    for (let i = 0; i <= nx; i++) for (let j = 0; j <= nz; j++) {
628	      const y = p.y(p.x0 + (p.x1 - p.x0) * i / nx, p.z0 + (p.z1 - p.z0) * j / nz);
629	      if (y < b.yMin) b.yMin = y; if (y > b.yMax) b.yMax = y;
630	    }
631	  }
632	  return b;
633	}
634	
635	/* Id các ô tới được từ (x, z, y): loang 4 hướng trên lưới mẫu 2 m neo tại điểm xuất phát; mỗi bước tra drGround từ cao độ điểm trước,
636	   nên chỉ đổi tầng ở chỗ hai ô nối nhau cùng cao độ. Trạng thái = (điểm lưới, ô). Dùng cho test và kiểm dữ liệu, không gọi mỗi khung */
637	export function drReach(net: DrNet, x: number, z: number, y: number): Set<string> {
638	  const out = new Set<string>();
639	  const p0 = drPadAt(net, x, z, y);
640	  if (p0 < 0) return out;
641	  const NP = net.pads.length, OFF = 1 << 14, SPAN = 1 << 15;    // chỉ số lưới ±16 384 bước (±32 km)
642	  const key = (i: number, j: number, p: number) => ((i + OFF) * SPAN + (j + OFF)) * NP + p;
643	  const seen = new Set<number>(), qi: number[] = [0], qj: number[] = [0], qp: number[] = [p0];
644	  seen.add(key(0, 0, p0)); out.add(net.pads[p0].id);
645	  const DI = [1, -1, 0, 0], DJ = [0, 0, 1, -1];
646	  for (let h = 0; h < qi.length; h++) {
647	    const i = qi[h], j = qj[h], pad = net.pads[qp[h]];
648	    const cx = x + i * REACH_STEP, cz = z + j * REACH_STEP, cy = pad.y(cx, cz);
649	    for (let d = 0; d < 4; d++) {
650	      const ni = i + DI[d], nj = j + DJ[d];
651	      const np = drPadAt(net, x + ni * REACH_STEP, z + nj * REACH_STEP, cy);
652	      if (np < 0) continue;
653	      const k = key(ni, nj, np);
654	      if (seen.has(k)) continue;
655	      seen.add(k); qi.push(ni); qj.push(nj); qp.push(np); out.add(net.pads[np].id);
656	    }
657	  }
658	  return out;
659	}
