/* ============================ Lái xe: va chạm thân xe nhiều tầng ============================
   Thân xe là hình chữ nhật có hướng (dài × rộng VF 3), tâm ở giữa hai trục bánh, cao độ p.y là mặt đường tại tâm.
   - Thân xe hợp lệ khi 9 điểm mẫu (4 góc, 4 trung điểm cạnh, tâm) đều có mặt đường cùng tầng (drGround hữu hạn từ yRef = p.y),
     không chồng vật cản nào có khoảng cao độ giao [y + sim.floor, y + chiều cao xe], không chồng hộp xe tự động cùng tầng (trừ hộp bỏ qua).
   - Luật xe tự động (spec §6): đầu mỗi drMove, hộp nào đã chồng tư thế xuất phát thì bỏ qua cả lượt đó; nhờ vậy xe tự động đâm tới
     thì đi xuyên, người chơi tự lao vào thì bị chặn, đã chồng thì vẫn lái ra được theo mọi hướng.
   - Đường thoát: tư thế đầu lượt đã chồng vật cản tĩnh hoặc ra ngoài ô thì nhận bước con không làm tệ hơn (drBad), để không kẹt vĩnh viễn.
   - Vật cản tra qua chỉ mục lưới ô DRC m (mẫu stroll/map.ts), giữ ngoài DrNet trong một WeakMap; dựng lười, nối thêm khi drAddSolids
     push vật cản mới, dựng lại khi mảng bị thay. Vật cản phủ quá nhiều ô để riêng danh sách "lớn", tra tuyến tính.
   - drFits / drMove / drSegClear chạy mỗi khung: không cấp phát (D-018), trừ khi lưới nối thêm vật cản hoặc mảng bỏ qua phải nới.
   Quy ước hướng: yaw = 0 mũi xe hướng +X; vectơ tiến (cos yaw, −sin yaw); dyaw > 0 là rẽ trái khi tiến. */
import { CONFIG } from '../../config';
import { drGround, type DrNet, type DrSolid } from './net';

export interface DrPose { x: number; y: number; z: number; yaw: number }
export interface DrBox { x: number; y: number; z: number; yaw: number; hl: number; hw: number }   // hộp xe tự động: nửa dài, nửa rộng

const CAR = CONFIG.drive.car, SIM = CONFIG.drive.sim;
const HL = CAR.length / 2, HW = CAR.width / 2;                       // nửa dài, nửa rộng thân xe, m
const AX = CAR.wheelbase / 2;                                        // tâm → trục sau, m
const REACH = AX + Math.hypot(HL, HW);                               // trục sau → góc xe xa nhất: quãng góc xe quét khi xoay dyaw là ≤ REACH · |dyaw|
const EPS = 1e-9;

/* ===== Chỉ mục lưới vật cản ===== */
const DRC = 16;          // cạnh ô lưới, m
const DR_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
const DR_OFF = 32768;    // dời chỉ số ô về số dương để ghép khóa (±524 km)
const drKey = (ix: number, iz: number): number => (ix + DR_OFF) * 65536 + (iz + DR_OFF);
interface DrGrid { arr: DrSolid[]; n: number; cells: Map<number, number[]>; big: number[] }
const GRIDS = new WeakMap<DrNet, DrGrid>();

function drIndexOne(g: DrGrid, s: DrSolid, i: number): void {
  const c = s.kind === 'circle';
  const x0 = c ? s.cx - s.r : s.x0, x1 = c ? s.cx + s.r : s.x1, z0 = c ? s.cz - s.r : s.z0, z1 = c ? s.cz + s.r : s.z1;
  const ix0 = Math.floor(x0 / DRC), ix1 = Math.floor(x1 / DRC), iz0 = Math.floor(z0 / DRC), iz1 = Math.floor(z1 / DRC);
  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > DR_BIG) { g.big.push(i); return; }
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const k = drKey(ix, iz); let list = g.cells.get(k);
    if (!list) { list = []; g.cells.set(k, list); }
    list.push(i);
  }
}
/* Lưới của net, cập nhật theo net.solids (drAddSolids chỉ push nên chỉ nối phần mới) */
function drGrid(net: DrNet): DrGrid {
  let g = GRIDS.get(net);
  if (!g || g.arr !== net.solids || g.n > net.solids.length) { g = { arr: net.solids, n: 0, cells: new Map(), big: [] }; GRIDS.set(net, g); }
  while (g.n < net.solids.length) { drIndexOne(g, net.solids[g.n], g.n); g.n++; }
  return g;
}

/* ===== Hình học ===== */
/* Thân xe (tâm x, z; cos c, sin s) chồng vật cản sol không (chỉ mặt bằng). Trục tiến f = (c, −s), trục ngang n = (s, c) */
function drHitSolid(sol: DrSolid, x: number, z: number, c: number, s: number): boolean {
  const ac = Math.abs(c), as = Math.abs(s);
  if (sol.kind === 'circle') {
    const dx = sol.cx - x, dz = sol.cz - z;
    let lf = dx * c - dz * s, ln = dx * s + dz * c;                   // tâm tròn trong hệ thân xe
    lf = lf > HL ? HL : lf < -HL ? -HL : lf; ln = ln > HW ? HW : ln < -HW ? -HW : ln;
    const ex = x + lf * c + ln * s - sol.cx, ez = z - lf * s + ln * c - sol.cz;
    return ex * ex + ez * ez < sol.r * sol.r - EPS;
  }
  const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
  if (Math.abs(dx) >= ex + HL * ac + HW * as - EPS) return false;    // tách theo trục X
  if (Math.abs(dz) >= ez + HL * as + HW * ac - EPS) return false;    // trục Z
  if (Math.abs(dx * c - dz * s) >= HL + ex * ac + ez * as - EPS) return false;   // trục tiến
  if (Math.abs(dx * s + dz * c) >= HW + ex * as + ez * ac - EPS) return false;   // trục ngang
  return true;
}
/* Độ lấn của thân xe vào vật cản sol (m, ≤ 0 là không chồng): hộp lấy độ chồng nhỏ nhất trên 4 trục tách (SAT);
   tròn lấy r − khoảng cách từ tâm tròn tới thân xe (tâm tròn nằm trong thân xe thì r + khoảng tới cạnh gần nhất). Chỉ dùng cho đường thoát */
function drPenSolid(sol: DrSolid, x: number, z: number, c: number, s: number): number {
  const ac = Math.abs(c), as = Math.abs(s);
  if (sol.kind === 'circle') {
    const dx = sol.cx - x, dz = sol.cz - z, lf = dx * c - dz * s, ln = dx * s + dz * c;
    const ef = Math.abs(lf) - HL, en = Math.abs(ln) - HW;
    if (ef <= 0 && en <= 0) return sol.r - Math.max(ef, en);
    const qf = ef > 0 ? ef : 0, qn = en > 0 ? en : 0;
    return sol.r - Math.hypot(qf, qn);
  }
  const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
  return Math.min(ex + HL * ac + HW * as - Math.abs(dx), ez + HL * as + HW * ac - Math.abs(dz),
    HL + ex * ac + ez * as - Math.abs(dx * c - dz * s), HW + ex * as + ez * ac - Math.abs(dx * s + dz * c));
}
/* Thân xe chồng hộp xe tự động b không (cùng tầng: chân hai xe chênh < chiều cao xe) */
function drHitBox(b: DrBox, x: number, y: number, z: number, c: number, s: number): boolean {
  if (Math.abs(b.y - y) >= CAR.height) return false;
  const bc = Math.cos(b.yaw), bs = Math.sin(b.yaw), dx = b.x - x, dz = b.z - z;
  /* bốn trục tách: f1 = (c, −s), n1 = (s, c), f2 = (bc, −bs), n2 = (bs, bc); hình chiếu nửa hộp lên trục a là hl|f·a| + hw|n·a| */
  const ff = c * bc + s * bs, fn = c * bs - s * bc;                  // f1·f2, f1·n2
  const nf = s * bc - c * bs, nn = s * bs + c * bc;                  // n1·f2, n1·n2
  if (Math.abs(dx * c - dz * s) >= HL + b.hl * Math.abs(ff) + b.hw * Math.abs(fn) - EPS) return false;
  if (Math.abs(dx * s + dz * c) >= HW + b.hl * Math.abs(nf) + b.hw * Math.abs(nn) - EPS) return false;
  if (Math.abs(dx * bc - dz * bs) >= b.hl + HL * Math.abs(ff) + HW * Math.abs(nf) - EPS) return false;
  if (Math.abs(dx * bs + dz * bc) >= b.hw + HL * Math.abs(fn) + HW * Math.abs(nn) - EPS) return false;
  return true;
}

/* ===== Thân xe hợp lệ ===== */
export function drFits(net: DrNet, p: DrPose, boxes: DrBox[], nBoxes: number, ignore: Uint8Array): boolean {
  const yRef = p.y, c = Math.cos(p.yaw), s = Math.sin(p.yaw);
  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
    const lf = i * HL, ln = j * HW;
    if (Number.isNaN(drGround(net, p.x + lf * c + ln * s, p.z - lf * s + ln * c, yRef))) return false;
  }
  const ya = yRef + SIM.floor, yb = yRef + CAR.height, sol = net.solids, g = drGrid(net);
  const big = g.big;
  for (let i = 0; i < big.length; i++) { const o = sol[big[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
  const R = HL * Math.abs(c) + HW * Math.abs(s), Rz = HL * Math.abs(s) + HW * Math.abs(c);   // nửa khung bao thân xe theo X, Z
  const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = g.cells.get(drKey(ix, iz));
    if (!list) continue;
    for (let i = 0; i < list.length; i++) { const o = sol[list[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
  }
  for (let i = 0; i < nBoxes; i++) if (!ignore[i] && drHitBox(boxes[i], p.x, yRef, p.z, c, s)) return false;
  return true;
}

/* ===== Đường thoát ===== */
/* Mức "tệ" của tư thế p không hợp lệ, ghi vào BAD_N, BAD_D:
   BAD_N = số điểm mẫu (trong 9) không có mặt đường cùng tầng; BAD_D = tổng độ lấn (drPenSolid > 0) vào các vật cản tĩnh cùng khoảng cao độ.
   Đường thoát nhận bước con khi cả hai không tăng: lấn theo SAT tăng ngay khi đi sâu thêm, và chỉ giảm sau khi vượt quá nửa vật cản,
   nên từ chỗ chồng nông không bao giờ đi xuyên qua được; đi vào vật cản mới thì tổng tăng. */
let BAD_N = 0, BAD_D = 0;
function drBad(net: DrNet, p: DrPose): void {
  const yRef = p.y, c = Math.cos(p.yaw), s = Math.sin(p.yaw);
  let n = 0, d = 0;
  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
    const lf = i * HL, ln = j * HW;
    if (Number.isNaN(drGround(net, p.x + lf * c + ln * s, p.z - lf * s + ln * c, yRef))) n++;
  }
  const ya = yRef + SIM.floor, yb = yRef + CAR.height, sol = net.solids, g = drGrid(net), big = g.big;
  for (let i = 0; i < big.length; i++) { const o = sol[big[i]]; if (o.y1 > ya && o.y0 < yb) { const q = drPenSolid(o, p.x, p.z, c, s); if (q > 0) d += q; } }
  const R = HL * Math.abs(c) + HW * Math.abs(s), Rz = HL * Math.abs(s) + HW * Math.abs(c);
  const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = g.cells.get(drKey(ix, iz));
    if (!list) continue;
    for (let k = 0; k < list.length; k++) {
      const i = list[k], o = sol[i];
      /* vật cản phủ nhiều ô được gặp nhiều lần: chỉ cộng ở ô đầu tiên (ô thấp nhất) mà nó và khung bao thân xe cùng có */
      if (!(o.y1 > ya && o.y0 < yb)) continue;
      const cx0 = o.kind === 'circle' ? o.cx - o.r : o.x0, cz0 = o.kind === 'circle' ? o.cz - o.r : o.z0;
      if (ix !== Math.max(ix0, Math.floor(cx0 / DRC)) || iz !== Math.max(iz0, Math.floor(cz0 / DRC))) continue;
      const q = drPenSolid(o, p.x, p.z, c, s); if (q > 0) d += q;
    }
  }
  BAD_N = n; BAD_D = d;
}

/* ===== Dời thân xe ===== */
let IGN = new Uint8Array(16);                                        // hộp bỏ qua trong lượt drMove hiện tại
const CUR: DrPose = { x: 0, y: 0, z: 0, yaw: 0 }, CAND: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
let mNet: DrNet, mBoxes: DrBox[], mN = 0;                            // tham số của lượt drMove hiện tại (tránh truyền lại / tạo closure)
let mEsc = false, mBadN = 0, mBadD = 0;                              // đang ở đường thoát (CUR không hợp lệ) và mức tệ của CUR
const BAD_TOL = 1e-6;                                                // m — dung sai làm tròn khi so tổng độ lấn

/* Thử đặt thân xe tại CAND (cao độ lấy lại theo mặt đường tại tâm); được thì chép sang CUR.
   CUR hợp lệ: CAND phải hợp lệ (luật thường). CUR không hợp lệ (đường thoát): CAND hợp lệ, hoặc không chạm hộp xe tự động
   chưa bỏ qua và mức tệ (drBad) không tăng; tâm không có mặt đường thì giữ cao độ cũ. */
function drTry(): boolean {
  let y = drGround(mNet, CAND.x, CAND.z, CUR.y);
  if (Number.isNaN(y)) { if (!mEsc) return false; y = CUR.y; }
  CAND.y = y;
  if (drFits(mNet, CAND, mBoxes, mN, IGN)) mEsc = false;
  else {
    if (!mEsc) return false;
    const c = Math.cos(CAND.yaw), s = Math.sin(CAND.yaw);
    for (let i = 0; i < mN; i++) if (!IGN[i] && drHitBox(mBoxes[i], CAND.x, y, CAND.z, c, s)) return false;
    drBad(mNet, CAND);
    if (BAD_N > mBadN || BAD_D > mBadD + BAD_TOL) return false;
    mBadN = BAD_N; mBadD = BAD_D;
  }
  CUR.x = CAND.x; CUR.y = CAND.y; CUR.z = CAND.z; CUR.yaw = CAND.yaw;
  return true;
}
/* Bước con kiểu xe đạp: trục sau đi sd theo hướng giữa bước, xe xoay sy; tâm = trục sau + AX theo hướng mới */
function drTryArc(sd: number, sy: number): boolean {
  const y0 = CUR.yaw, ym = y0 + sy / 2, y1 = y0 + sy;
  const rx = CUR.x - AX * Math.cos(y0) + sd * Math.cos(ym), rz = CUR.z + AX * Math.sin(y0) - sd * Math.sin(ym);
  CAND.x = rx + AX * Math.cos(y1); CAND.z = rz - AX * Math.sin(y1); CAND.yaw = y1;
  return drTry();
}
function drTryShift(dx: number, dz: number): boolean {
  CAND.x = CUR.x + dx; CAND.z = CUR.z + dz; CAND.yaw = CUR.yaw;
  return drTry();
}

/* Dời thân xe từ p quãng dist (m, âm = lùi; quãng của trục sau) và xoay dyaw (rad), kết quả vào out (out có thể là p).
   Chia bước con ≤ sim.sub (tính cả quãng góc xe quét khi xoay). Bước con bị chặn thì thử: chỉ tịnh tiến (bỏ xoay), chỉ thành phần X,
   chỉ thành phần Z (trượt dọc vật cản thẳng trục); không được thì dừng. Tư thế đầu lượt đã chồng vật cản tĩnh / ra ngoài ô
   (chỗ xuất phát đặt sai, vật cản thêm đè lên xe) thì đi theo đường thoát của drTry cho tới khi hợp lệ trở lại. Trả phần quãng đã đi theo hướng định đi:
   1 = trọn; trượt theo một trục tính bằng bình phương cos góc giữa trục đó và hướng định đi; 0 = đứng hẳn. */
export function drMove(net: DrNet, p: DrPose, dist: number, dyaw: number, boxes: DrBox[], nBoxes: number, out: DrPose): number {
  if (IGN.length < nBoxes) IGN = new Uint8Array(Math.max(nBoxes, IGN.length * 2));
  const c0 = Math.cos(p.yaw), s0 = Math.sin(p.yaw);
  for (let i = 0; i < nBoxes; i++) IGN[i] = drHitBox(boxes[i], p.x, p.y, p.z, c0, s0) ? 1 : 0;
  mNet = net; mBoxes = boxes; mN = nBoxes;
  CUR.x = p.x; CUR.y = p.y; CUR.z = p.z; CUR.yaw = p.yaw;
  mEsc = !drFits(net, CUR, boxes, nBoxes, IGN);                      // hộp chồng sẵn đã bỏ qua: không hợp lệ chỉ vì vật cản tĩnh / ra ngoài ô
  if (mEsc) { drBad(net, CUR); mBadN = BAD_N; mBadD = BAD_D; }
  const n =Math.max(1, Math.ceil((Math.abs(dist) + Math.abs(dyaw) * REACH) / SIM.sub));
  const sd = dist / n, sy = dyaw / n;
  let done = 0;
  for (let k = 0; k < n; k++) {
    if (drTryArc(sd, sy)) { done += 1; continue; }
    if (sd === 0) break;                                              // xoay tại chỗ bị chặn
    if (sy !== 0 && drTryShift(sd * Math.cos(CUR.yaw), -sd * Math.sin(CUR.yaw))) { done += 1; continue; }
    const tx = sd * Math.cos(CUR.yaw), tz = -sd * Math.sin(CUR.yaw);
    if (Math.abs(tx) > EPS && drTryShift(tx, 0)) { done += tx * tx / (sd * sd); continue; }
    if (Math.abs(tz) > EPS && drTryShift(0, tz)) { done += tz * tz / (sd * sd); continue; }
    break;
  }
  out.x = CUR.x; out.y = CUR.y; out.z = CUR.z; out.yaw = CUR.yaw;
  mNet = null; mBoxes = null;
  return done / n;
}

/* ===== Đoạn thẳng (camera) ===== */
/* Tham số t ∈ [0, 1] nơi đoạn a + t·d đi vào vật cản o (khối hộp / trụ đứng giữa y0..y1); 1 nếu không cắt; 0 nếu a ở trong */
function drSegHit(o: DrSolid, ax: number, ay: number, az: number, dx: number, dy: number, dz: number): number {
  let t0 = -Infinity, t1 = Infinity;
  if (Math.abs(dy) < EPS) { if (ay < o.y0 || ay > o.y1) return 1; }
  else { const a = (o.y0 - ay) / dy, b = (o.y1 - ay) / dy; t0 = a < b ? a : b; t1 = a < b ? b : a; }
  if (o.kind === 'circle') {
    const ox = ax - o.cx, oz = az - o.cz, A = dx * dx + dz * dz, B = 2 * (ox * dx + oz * dz), C = ox * ox + oz * oz - o.r * o.r;
    if (A < EPS) { if (C > 0) return 1; }
    else {
      const D = B * B - 4 * A * C;
      if (D < 0) return 1;
      const q = Math.sqrt(D), a = (-B - q) / (2 * A), b = (-B + q) / (2 * A);
      if (a > t0) t0 = a; if (b < t1) t1 = b;
    }
  } else {
    if (Math.abs(dx) < EPS) { if (ax < o.x0 || ax > o.x1) return 1; }
    else { const a = (o.x0 - ax) / dx, b = (o.x1 - ax) / dx; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
    if (Math.abs(dz) < EPS) { if (az < o.z0 || az > o.z1) return 1; }
    else { const a = (o.z0 - az) / dz, b = (o.z1 - az) / dz; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
  }
  if (t0 > t1 || t1 < 0 || t0 > 1) return 1;
  return t0 > 0 ? t0 : 0;
}

/* Phần đoạn thẳng a → b (0..1) đi được trước khi chạm vật cản (cùng khoảng cao độ, vì vật cản có y0..y1 tuyệt đối) */
export function drSegClear(net: DrNet, ax: number, ay: number, az: number, bx: number, by: number, bz: number): number {
  const g = drGrid(net), sol = net.solids, dx = bx - ax, dy = by - ay, dz = bz - az;
  let t = 1;
  const big = g.big;
  for (let i = 0; i < big.length; i++) { const h = drSegHit(sol[big[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
  const ix0 = Math.floor(Math.min(ax, bx) / DRC), ix1 = Math.floor(Math.max(ax, bx) / DRC);
  const iz0 = Math.floor(Math.min(az, bz) / DRC), iz1 = Math.floor(Math.max(az, bz) / DRC);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = g.cells.get(drKey(ix, iz));
    if (!list) continue;
    for (let i = 0; i < list.length; i++) { const h = drSegHit(sol[list[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
  }
  return t;
}
/* ============================ Lái xe: chuyển động theo số liệu VF 3 ============================
   Mô hình "xe đạp" động học trên mặt bằng (spec §5.2): vị trí, hướng, tốc độ dọc có dấu, góc lái; không mô phỏng lốp, treo, trượt.
   - Tăng tốc: a = a0 không đổi tới 50 km/h (a0 = 50 km/h / t50, qua đúng mốc thứ nhất), sau đó a = a0 · v50 / v · (1 − u^k)
     với u = (v − v50) / (vMax − v50): giảm theo công suất không đổi và về 0 tại vMax. Số mũ k giải một lần (chia đôi) sao cho tới
     99 % vMax (27,5 m/s ≈ 100 km/h, vì đường cong chỉ tiệm cận vMax) đúng t100.
   - Lái: góc lái lớn nhất asin(wheelbase / turnRadius) (bán kính quay vòng tính ở tâm trục trước); tốc độ cao thì giới hạn thêm
     sao cho gia tốc ngang v² · tan(góc) / wheelbase ≤ latMax. Góc lái tiến về đích theo steerRate, tự trả về 0 theo steerReturn
     (cả hai là phần góc lái lớn nhất mỗi giây).
   - Phanh / lùi: phanh khi đang tiến; |v| < sim.revV mà giữ phanh, không ga thì lùi dần tới reverseMax; đang lùi mà đạp ga thì phanh
     về 0 rồi mới tiến. Nhả hết thì chậm dần theo coast, không tự lùi. Phanh tay hãm handBrake, không trượt. Dốc không đổi gia tốc.
   - drStep chia dt thành bước ≤ sim.dt (tối đa sim.steps bước, phần dư bỏ); mỗi bước dời thân xe bằng drMove (collide.ts);
     bị chặn thì mất phần tốc độ hướng vào vật cản một lần (đâm thẳng thì đứng hẳn, cọ chéo còn phần chiếu dọc vật cản),
     đang cọ thì hãm thêm perf.scrape (m/s²); kết quả không phụ thuộc tần số khung.
   Không cấp phát mỗi khung (D-018). Không import three. */
import { CONFIG } from '../../config';
import { drGround, type DrNet } from './net';
import { drSpawnPose } from './roadData';
import { drMove, type DrPose, type DrBox } from './collide';

export interface DrState extends DrPose { pitch: number; v: number; steer: number; wheel: number; braking: boolean; evac: number; slide?: number; touch?: number }   // v: m/s có dấu; steer: rad; wheel: góc quay bánh tích lũy (rad); slide: phần tốc độ còn giữ trong lần chạm vật cản hiện tại (1 = không chạm, mặc định); touch: s còn coi là đang chạm (mặc định 0)
export interface DrInput { gas: number; brake: number; steer: number; hand: boolean }   // gas, brake: 0..1; steer: −1..1

const CAR = CONFIG.drive.car, P = CONFIG.drive.perf, SIM = CONFIG.drive.sim;
const L = CAR.wheelbase;
const V50 = 50 / 3.6;                                                // m/s — mốc 0–50 km/h của t50
const STEER_GEOM = Math.asin(L / P.turnRadius);                     // rad — góc lái lớn nhất theo hình học

/* ===== Đường cong tăng tốc ===== */
let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
function drAccelK(v: number, k: number): number {
  if (v <= V50) return A0;
  if (v >= P.vMax) return 0;
  const u = (v - V50) / (P.vMax - V50);
  return A0 * V50 / v * (1 - Math.pow(u, k));
}
/* Thời gian 0 → 0,99 vMax với số mũ k (tích phân dv / a, điểm giữa) */
function drT100(k: number): number {
  const vt = 0.99 * P.vMax, N = 2000, h = (vt - V50) / N;
  let t = V50 / A0;
  for (let i = 0; i < N; i++) t += h / drAccelK(V50 + (i + 0.5) * h, k);
  return t;
}
function drFitAccel(): void {
  A0 = V50 / P.t50;
  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: drT100 giảm theo k
  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (drT100(m) > P.t100) lo = m; else hi = m; }
  KEXP = (lo + hi) / 2;
}
/* m/s² khi đạp hết ga ở tốc độ v ≥ 0 */
export function drAccel(v: number): number {
  if (Number.isNaN(KEXP)) drFitAccel();
  return drAccelK(v, KEXP);
}

/* rad — góc lái lớn nhất ở tốc độ v (dấu bỏ qua) */
export function drSteerMax(v: number): number {
  const a = Math.abs(v);
  if (a < 1e-6) return STEER_GEOM;
  const lim = Math.atan(L * P.latMax / (a * a));
  return lim < STEER_GEOM ? lim : STEER_GEOM;
}

const drToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);

/* Dốc dọc từ cao độ mặt đường tại trục trước / sau; giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
function drPitch(s: DrState, net: DrNet): void {
  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
}

/* Xe mới ở chỗ xuất phát của slot, đứng yên trên mặt đường cao nhất tại đó (mặt cầu) */
export function drCreate(net: DrNet, slot: number): DrState {
  const sp = drSpawnPose(slot);
  let y = -Infinity;
  for (const p of net.pads) {
    if (sp.x < p.x0 || sp.x > p.x1 || sp.z < p.z0 || sp.z > p.z1) continue;
    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
    y = Math.max(y, p.y(sp.x, sp.z));
  }
  const s: DrState = { x: sp.x, y: Number.isFinite(y) ? y : CONFIG.roadY, z: sp.z, yaw: sp.yaw, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0, slide: 1, touch: 0 };
  drPitch(s, net);
  return s;
}

const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };

/* Một bước h ≤ sim.dt */
function drStep1(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
  const g = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, b = inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
  let v = s.v, braking = false;
  /* tốc độ */
  if (inp.hand) { v = drToward0(v, P.handBrake * h); braking = true; }
  else if (b > 0 && g === 0) {
    if (v >= SIM.revV) { v = Math.max(0, v - b * P.brake * h); braking = true; }                       // đang tiến: phanh
    else v = Math.max(-P.reverseMax, v - b * (v > 0 ? P.brake : drAccel(-v)) * h);                   // gần đứng / đang lùi: lùi dần
  } else if (g > 0 && b === 0) {
    if (v < 0) { v = Math.min(0, v + g * P.brake * h); braking = true; }                             // đang lùi: phanh về 0 rồi mới tiến
    else v = Math.min(P.vMax, v + g * drAccel(v) * h);
  } else if (g > 0 && b > 0) { v = drToward0(v, b * P.brake * h); braking = true; }
  else v = drToward0(v, P.coast * h);
  /* góc lái */
  const lim = drSteerMax(v), want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer;
  let st = s.steer;
  if (want === 0) st = drToward0(st, P.steerReturn * STEER_GEOM * h);
  else {
    const tgt = want * lim, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_GEOM * h;
    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
  }
  if (st > lim) st = lim; else if (st < -lim) st = -lim;
  /* dời thân xe */
  const dist = v * h, f = drMove(net, s, dist, dist * Math.tan(st) / L, boxes, nBoxes, MOVED);
  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
  /* va chạm: phần quãng f là cos² góc giữa hướng trượt và hướng xe, nên √f là phần tốc độ chiếu theo hướng trượt.
     Chỉ mất phần hướng vào vật cản khi √f xuống dưới mức nhỏ nhất đã mất trong lần chạm này (slide), không lặp lại mỗi bước
     khi vẫn tì vào; đang cọ thì hãm thêm perf.scrape; không bị chặn quá sim.touch giây thì coi như đã rời vật cản. */
  let slide = s.slide ?? 1, touch = s.touch ?? 0;
  if (f < 1) {
    if (touch > 0) v = drToward0(v, P.scrape * h);                   // đang cọ: hãm thêm
    const q = f > 0 ? Math.sqrt(f) : 0;
    if (q === 0) v = 0;                                              // đứng hẳn: đâm thẳng, hoặc tì thẳng vào mà vẫn đạp ga
    else if (q < slide) v *= q / slide;
    if (q < slide) slide = q;
    touch = SIM.touch;
  } else if (touch > 0) { touch -= h; if (touch <= 0) { touch = 0; slide = 1; } }
  s.slide = slide; s.touch = touch;
  s.v = v; s.steer = st; s.braking = braking;
  s.wheel += dist * f / (CAR.wheelDia / 2);
  drPitch(s, net);
}

/* Bước mô phỏng cho khung dài dt (s) */
export function drStep(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
  let rem = dt;
  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
    const h = rem < SIM.dt ? rem : SIM.dt;
    drStep1(s, inp, net, boxes, nBoxes, h);
    rem -= h;
  }
}
/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
   camera sau xe (camera) với vòng animate, phím, chuột. Mẫu: explore/stroll/index.ts.
   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn cũng lái một mình (sảnh nhiều người: Task 10–11).
   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
     Sơ tán xe đang đứng trên nhịp quay: Task 8.
   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
   - Xe của mình là xe slot 0 của drCars (màu slot 0 khi lái một mình); xe và bánh chỉ vào cảnh khi vào chế độ (góc nhìn cũ không thêm lệnh vẽ).
   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
   Mỗi khung không cấp phát (D-018). */
import type * as THREE from 'three';
import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
import { composer, onResize } from '../../core/postprocessing';
import { cam } from '../../views/state';
import { CONFIG } from '../../config';
import { driveView } from '../../environment/driveRoads';
import { drMakeNet, drSetGate, type DrNet } from './net';
import { drBuildPads, DR_GATE_SWING } from './roadData';
import { drBuildSolids } from './solids';
import { drCollectRuntime, drSceneStats } from './sceneSolids';
import { drCreate, drStep, type DrState, type DrInput } from './motion';
import type { DrBox } from './collide';
import { drCarLoad, drCarSetWarm } from './car';
import { drCars } from './cars';
import { drCamPlace, drCamDrag, type DrCam } from './camera';
import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
import { exNightStep } from '../nightShows';
import type { SwingController } from '../../bridges/song-han/SwingController';

const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0)

/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
drCarSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});

let net: DrNet | null = null;
let state: DrState | null = null;
let ctrl: SwingController | null = null;
const drKeys = new Set<string>();  // e.code đang giữ
const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
const NO_BOXES: DrBox[] = [];      // hộp xe tự động: Task 8

const active = () => cam.mode === 'car' && state !== null;
const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');

/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại */
function drEnsureNet(): DrNet {
  if (!net) {
    net = drMakeNet(drBuildPads(), drBuildSolids());
    drCollectRuntime(net, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
  }
  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  return net;
}

/* Một bước: cổng nhịp quay, chuyển động, hình xe, camera, hiệu ứng đêm */
function advance(dt: number, inp: DrInput): void {
  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
  drStep(state!, inp, net!, NO_BOXES, 0, dt);
  drCars.place(DR_SELF, state!);
  drCamPlace(camera, state!, camS, net!, dt);
  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
  exNightStep(dt, false);
}

/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
   Dùng cho test (__app.drive) và đặt lại vị trí */
function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
  if (!net) return;
  const s = drCreate(net, DR_SOLO_SLOT);
  let gy = -Infinity;
  for (const p of net.pads) {
    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
    gy = Math.max(gy, p.y(x, z));
  }
  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
  state = s;
  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
  drCars.place(DR_SELF, s);
  drCamPlace(camera, s, camS, net, 0, true);
  controls.target.set(s.x, s.y, s.z);
}

export const drive = {
  active,
  get state(): DrState | null { return state; },
  get net(): DrNet | null { return net; },
  get cam(): DrCam { return camS; },
  /* Vào lái. solo: lái một mình (hiện luôn là một mình; slot nhiều người ở Task 11) */
  start(solo = true): void {
    const n = drEnsureNet();
    state = drCreate(n, DR_SOLO_SLOT);
    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
    drCars.sync([{ slot: DR_SELF }]);
    if (!drCars.group.parent) scene.add(drCars.group);
    drCars.place(DR_SELF, state);
    driveView.far = CONFIG.drive.tunnelFar;
    drKeys.clear();
    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
    drCamPlace(camera, state, camS, n, 0, true);
    controls.target.set(state.x, state.y, state.z);
    document.body.classList.add('explore', 'drive');
  },
  /* Chế độ xem bám xe người khác: Task 11. Hiện chưa có phiên lái nhiều người nên lái một mình */
  startWatching(): void { drive.start(true); },
  update(dt: number): void {
    if (!active()) return;
    advance(dt, drInputFromKeys(drKeys, _inp));
  },
  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
  afterRender(): void { /* chưa có việc */ },
  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau) */
  stop(): void {
    if (!active()) return;
    state = null; drKeys.clear();
    drCars.clear(); drCars.group.removeFromParent();
    driveView.far = 1;
    document.body.classList.remove('drive');
    cam.mode = 'orbit'; controls.enabled = true;
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
  step(dt: number, inp: DrInput): void { if (active()) advance(dt, inp); },
  placeAt: drPlaceAt,
  stats: drSceneStats,
  preload(): void { void drCarLoad(); }
};

/* onExit: thoát chung (explore.exit); Task 11 dùng khi mất kết nối lúc đang xem, lái một mình chưa cần */
export function setupDrive(c: SwingController, onExit: () => void): void {
  ctrl = c;
  window.addEventListener('keydown', (e) => {
    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
    if (!DR_KEYS.has(e.code)) return;
    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
    drKeys.add(e.code);
  });
  window.addEventListener('keyup', (e) => {
    drKeys.delete(e.code);
    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
  });
  const drop = drBindDrop(window, document, drKeys);
  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
  /* Kéo chuột trái trên canvas: xoay camera quanh xe (cảm ứng ở Task 9) */
  let dragId = -1, lx = 0, ly = 0;
  canvas.addEventListener('pointerdown', (e) => {
    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
    canvas.setPointerCapture(e.pointerId);
  });
  canvas.addEventListener('pointermove', (e) => {
    if (e.pointerId !== dragId) return;
    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
    lx = e.clientX; ly = e.clientY;
  });
  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
  canvas.addEventListener('pointerup', end);
  canvas.addEventListener('pointercancel', end);
  canvas.addEventListener('lostpointercapture', end);
}
/* ============================ Lái xe: mạng đường nhiều tầng (DrNet) ============================
   Mạng đường là danh sách ô mặt đường chữ nhật thẳng trục, mỗi ô có hàm cao độ riêng. Ô chồng nhau trên mặt bằng
   (đường ven sông dưới dốc cầu, đường trên hầm) tách tầng nhờ so cao độ với cao độ hiện tại của xe (± stepMax).
   Thuần toán học: chỉ import CONFIG; không dựng cảnh, không đụng DOM. Dữ liệu ô sinh ở roadData.ts. */
import { CONFIG } from '../../config';

export interface DrPad { id: string; kind: 'road' | 'bridge' | 'tunnel' | 'slip' | 'junction'; x0: number; x1: number; z0: number; z1: number; y: (x: number, z: number) => number; gate?: string }
export interface DrSolid { kind: 'rect' | 'circle'; x0?: number; x1?: number; z0?: number; z1?: number; cx?: number; cz?: number; r?: number; y0: number; y1: number }   // y0..y1: cao độ tuyệt đối (m) mà vật cản chiếm
export interface DrNet { pads: DrPad[]; solids: DrSolid[]; closed: Set<string> }

const REACH_STEP = 2;                                               // m — bước lưới mẫu của drReach: ô hẹp nhất 3,35 m nên ô nào cũng có điểm mẫu; khe hẹp hơn bước (dải giữa Thuận Phước 1,0 m) có thể bị bước qua, nên drReach chỉ để kiểm liên thông

export function drMakeNet(pads: DrPad[], solids: DrSolid[]): DrNet {
  return { pads, solids: solids.slice(), closed: new Set() };
}
/* net.solids chỉ được thêm bằng push (chỉ mục lưới của collide.ts dựa vào điều đó); barie Cầu sông Hàn chặn bằng cổng của ô, không thêm / xóa vật cản */
export function drAddSolids(net: DrNet, more: DrSolid[]): void {
  for (const s of more) net.solids.push(s);
}
/* Đóng / mở cổng: ô mang cổng đang đóng coi như không có (nhịp quay Cầu sông Hàn khi cầu quay) */
export function drSetGate(net: DrNet, gate: string, closed: boolean): void {
  if (closed) net.closed.add(gate); else net.closed.delete(gate);
}

/* Chỉ số ô chứa (x, z) có cao độ gần yRef nhất trong ± stepMax; −1 nếu không có. Duyệt tuyến tính, không cấp phát */
function drPadAt(net: DrNet, x: number, z: number, yRef: number): number {
  const pads = net.pads, step = CONFIG.drive.stepMax;
  let best = -1, bestD = Infinity;
  for (let i = 0; i < pads.length; i++) {
    const p = pads[i];
    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
    const d = Math.abs(p.y(x, z) - yRef);
    if (d <= step && d < bestD) { best = i; bestD = d; }
  }
  return best;
}
/* Cao độ mặt đường tại (x, z) ở tầng gần yRef nhất; NaN nếu không có ô nào cùng tầng */
export function drGround(net: DrNet, x: number, z: number, yRef: number): number {
  const i = drPadAt(net, x, z, yRef);
  return i < 0 ? NaN : net.pads[i].y(x, z);
}

/* Khung bao mặt bằng và cao độ của mọi ô (cao độ lấy mẫu mỗi ≤ 2 m theo hai trục) */
export function drBounds(net: DrNet): { x0: number; x1: number; z0: number; z1: number; yMin: number; yMax: number } {
  const b = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity, yMin: Infinity, yMax: -Infinity };
  for (const p of net.pads) {
    b.x0 = Math.min(b.x0, p.x0); b.x1 = Math.max(b.x1, p.x1); b.z0 = Math.min(b.z0, p.z0); b.z1 = Math.max(b.z1, p.z1);
    const nx = Math.ceil((p.x1 - p.x0) / 2), nz = Math.ceil((p.z1 - p.z0) / 2);
    for (let i = 0; i <= nx; i++) for (let j = 0; j <= nz; j++) {
      const y = p.y(p.x0 + (p.x1 - p.x0) * i / nx, p.z0 + (p.z1 - p.z0) * j / nz);
      if (y < b.yMin) b.yMin = y; if (y > b.yMax) b.yMax = y;
    }
  }
  return b;
}

/* Id các ô tới được từ (x, z, y): loang 4 hướng trên lưới mẫu 2 m neo tại điểm xuất phát; mỗi bước tra drGround từ cao độ điểm trước,
   nên chỉ đổi tầng ở chỗ hai ô nối nhau cùng cao độ. Trạng thái = (điểm lưới, ô). Dùng cho test và kiểm dữ liệu, không gọi mỗi khung */
export function drReach(net: DrNet, x: number, z: number, y: number): Set<string> {
  const out = new Set<string>();
  const p0 = drPadAt(net, x, z, y);
  if (p0 < 0) return out;
  const NP = net.pads.length, OFF = 1 << 14, SPAN = 1 << 15;    // chỉ số lưới ±16 384 bước (±32 km)
  const key = (i: number, j: number, p: number) => ((i + OFF) * SPAN + (j + OFF)) * NP + p;
  const seen = new Set<number>(), qi: number[] = [0], qj: number[] = [0], qp: number[] = [p0];
  seen.add(key(0, 0, p0)); out.add(net.pads[p0].id);
  const DI = [1, -1, 0, 0], DJ = [0, 0, 1, -1];
  for (let h = 0; h < qi.length; h++) {
    const i = qi[h], j = qj[h], pad = net.pads[qp[h]];
    const cx = x + i * REACH_STEP, cz = z + j * REACH_STEP, cy = pad.y(cx, cz);
    for (let d = 0; d < 4; d++) {
      const ni = i + DI[d], nj = j + DJ[d];
      const np = drPadAt(net, x + ni * REACH_STEP, z + nj * REACH_STEP, cy);
      if (np < 0) continue;
      const k = key(ni, nj, np);
      if (seen.has(k)) continue;
      seen.add(k); qi.push(ni); qj.push(nj); qp.push(np); out.add(net.pads[np].id);
    }
  }
  return out;
}

