const TP_IN = TP.median / 2;                                        // 0,5
const TP_OUT = TP_IN + 2 * TP.laneWidth;                            // 7,5
const TP_END = TP.endX + TP.embankment;                             // 1047,5 — đường đắp về mặt đất

