      if (a * a + b * b + c * c < 1e-12) continue;                 // scale 0: xe đang ẩn
      const tx = m[o + 12], ty = m[o + 13], tz = m[o + 14];
      const wx = W[0] * tx + W[4] * ty + W[8] * tz + W[12], wz = W[2] * tx + W[6] * ty + W[10] * tz + W[14];
