// Lái thử Task 8 (tạm, không commit): xe tự động chặn / đi xuyên, sơ tán nhịp quay Cầu sông Hàn. Đọc dist/.
import { pathToFileURL, fileURLToPath } from 'node:url';
const REPO = 'D:/2026 - Tuan/danang-vite/';
const { serveDir, launch, openApp, frames } = await import(pathToFileURL(REPO + 'tests/lib.mjs').href);
const SCREENS = REPO + 'tests/screens/';
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);

const srv = await serveDir(REPO + 'dist/');
const browser = await launch();
const out = {};
try {
  const { page: P, errors } = await openApp(browser, srv.url + '?explore=drive', { width: 640, height: 360 });
  await P.waitForFunction(() => window.__app.drive.active(), null, { timeout: 240000, polling: 1000 });
  log('đang lái', await P.evaluate(() => { const s = window.__app.drive.state; return { x: s.x, z: s.z, y: s.y }; }));

  /* helper trong trang */
  await P.evaluate(() => {
    const a = window.__app, D = a.drive, HL = 3.19 / 2;
    const ground = (x, z, yRef) => { let best = NaN, bd = Infinity; for (const p of D.net.pads) { if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue; if (p.gate !== undefined && D.net.closed.has(p.gate)) continue; const d = Math.abs(p.y(x, z) - yRef); if (d <= 0.6 && d < bd) { bd = d; best = p.y(x, z); } } return best; };
    const city = () => a.traffic.city();
    const cityMesh = () => a.scene.getObjectByName('traffic-city');
    const vis = (i) => { const e = cityMesh().instanceMatrix.array; return Math.hypot(e[i * 16], e[i * 16 + 1], e[i * 16 + 2]) > 1e-6; };
    const pos = (i) => { const e = cityMesh().instanceMatrix.array; return { x: e[i * 16 + 12], y: e[i * 16 + 13], z: e[i * 16 + 14] }; };
    const T = a.traffic.types;
    window.__t8 = { ground, city, vis, pos, T, HL };
  });

  /* (a) đặt xe sau một xe tự động trên Cầu Rồng, tiến tới: dừng sau đuôi */
  const A = await P.evaluate(() => {
    const a = window.__app, D = a.drive, t = window.__t8, list = t.city(), paths = a.traffic.paths;
    let pick = -1;
    for (let i = 0; i < list.length; i++) { const v = list[i]; if (v.path === paths.axis && v.dir > 0 && v.lane === 4.875 && v.type === 'car' && v.s > -200 && v.s < 150 && t.vis(i)) { pick = i; break; } }
    if (pick < 0) return { err: 'không có xe phù hợp' };
    const p0 = t.pos(pick), hl = t.T.car.len / 2;
    D.placeAt(p0.x - 10, p0.z, 0);
    const inp = { gas: 1, brake: 0, steer: 0, hand: false };
    for (let i = 0; i < 90; i++) D.step(1 / 30, inp);                // 3 s, xe tự động đứng yên trong vòng lặp đồng bộ
    const s = D.state, p1 = t.pos(pick);
    return { pick, ai: p1, aiTail: p1.x - hl, carNose: s.x + t.HL, x: s.x, z: s.z, v: s.v };
  });
  log('(a)', A);
  out.a = A;
  await frames(P, 2);
  await P.screenshot({ path: SCREENS + 'drive-ai-block.png' });

  /* (b) xe đứng yên ngay trước một xe tự động cùng làn đang chạy tới: xe tự động đi qua, xe mình không bị đẩy, rồi vẫn lái ra được */
  const B0 = await P.evaluate(() => {
    const a = window.__app, D = a.drive, t = window.__t8, list = t.city(), paths = a.traffic.paths;
    let pick = -1;
    for (let i = 0; i < list.length; i++) { const v = list[i]; if (v.path === paths.axis && v.dir > 0 && v.lane === 4.875 && v.type === 'car' && v.s > -250 && v.s < 100 && t.vis(i)) { pick = i; break; } }
    const p0 = t.pos(pick), hl = t.T.car.len / 2;
    D.placeAt(p0.x + hl + t.HL + 0.6, p0.z, 0);                       // mũi xe tự động cách đuôi xe mình 0,6 m
    window.__t8.b = { pick, x0: D.state.x, z0: D.state.z, log: [] };
    return { pick, ai: p0, speed: list[pick].speed, x: D.state.x };
  });
  log('(b) bắt đầu', B0);
  /* chờ khung thật cho xe tự động chạy tới / qua (main.ts: dt ≤ 0,05 s mỗi khung) */
  let B = null;
  for (let k = 0; k < 120; k++) {
    await frames(P, 1);
    B = await P.evaluate(() => { const t = window.__t8, s = window.__app.drive.state, p = t.pos(t.b.pick); t.b.log.push([p.x, s.x]); return { ai: p.x, x: s.x, z: s.z, x0: t.b.x0, z0: t.b.z0, n: t.b.log.length }; });
    if (k === 6) await P.screenshot({ path: SCREENS + 'drive-ai-through.png' });
    if (B.ai > B.x + 6) break;
  }
  log('(b) sau khi xe tự động qua', B);
  out.b = B;
  const B2 = await P.evaluate(() => {
    const D = window.__app.drive, x0 = D.state.x;
    for (let i = 0; i < 60; i++) D.step(1 / 30, { gas: 1, brake: 0, steer: 0, hand: false });
    return { x0, x1: D.state.x };
  });
  log('(b) lái ra', B2);
  out.b2 = B2;

  /* (c) giữa nhịp quay Cầu sông Hàn, kích cầu quay 30× */
  const C0 = await P.evaluate(() => {
    const a = window.__app, D = a.drive, c = a.songHan.ctrl;
    D.placeAt(0, c.cfg.z + c.cfg.lane, 0);
    window.__t8.c = [];
    const tick = () => { const s = D.state; window.__t8.c.push({ st: c.state, ang: c.angle, lift: c.lift, x: s.x, y: s.y, z: s.z, ev: s.evac, ct: c.t }); window.__t8.raf = requestAnimationFrame(tick); };
    tick();
    c.start(30);
    return { x: D.state.x, z: D.state.z, y: D.state.y, deckY: c.cfg.deckY, barrierX: c.cfg.barrierX };
  });
  log('(c) bắt đầu', C0);
  let shotEvac = false, C = null;
  for (let k = 0; k < 80; k++) {
    await frames(P, 1);
    C = await P.evaluate(() => { const L = window.__t8.c; return L[L.length - 1]; });
    if (!shotEvac && C.ev > 0 && Math.abs(C.x) > 20) { await P.screenshot({ path: SCREENS + 'drive-swing-evac.png' }); shotEvac = true; }
    if (C.st === 'ROTATING_OPEN' && C.ang > 0.05) break;
  }
  const trace = await P.evaluate(() => window.__t8.c);
  const firstRot = trace.find((r) => r.st === 'ROTATING_OPEN');
  const lastEvac = trace.filter((r) => r.ev > 0).pop();
  const evacDone = trace.find((r, i) => i > 0 && trace[i - 1].ev > 0 && r.ev === 0);
  log('(c) vết', trace.length, 'khung; khung đầu ROTATING_OPEN', firstRot, 'khung sơ tán cuối', lastEvac, 'xong', evacDone);
  out.c = { first: trace[0], firstRot, lastEvac, evacDone, maxY: Math.max(...trace.map((r) => r.y)), minY: Math.min(...trace.map((r) => r.y)), last: C };
  await P.screenshot({ path: SCREENS + 'drive-swing-open.png' });
  /* lúc nhịp mở: lái thử vào nhịp → bị chặn ở mép */
  const C2 = await P.evaluate(() => {
    const D = window.__app.drive, s = D.state, x0 = s.x;
    s.yaw = Math.PI;                                                   // quay mũi về phía nhịp (Tây) — chỉ cho thử chặn
    let minAbs = Math.abs(s.x);
    for (let i = 0; i < 150; i++) { D.step(1 / 30, { gas: 1, brake: 0, steer: 0, hand: false }); minAbs = Math.min(minAbs, Math.abs(s.x)); }
    return { x0, x: s.x, minAbs, y: s.y, ev: s.evac };
  });
  log('(c) lái vào nhịp khi đang mở', C2);
  out.c2 = C2;
  /* tua cầu: đóng lại */
  await P.evaluate(() => { const c = window.__app.songHan.ctrl; c.speed = 3000; window.__kc = setInterval(() => c.requestClose(), 100); });
  await P.waitForFunction(() => window.__app.songHan.ctrl.state === 'CLOSED', null, { timeout: 600000, polling: 1000 });
  await P.evaluate(() => { clearInterval(window.__kc); cancelAnimationFrame(window.__t8.raf); });
  await frames(P, 2);
  const C3 = await P.evaluate(() => {
    const D = window.__app.drive, s = D.state, t = window.__t8, x0 = s.x;
    let minY = Infinity, maxY = -Infinity;
    for (let i = 0; i < 360; i++) { D.step(1 / 30, { gas: 1, brake: 0, steer: 0, hand: false }); minY = Math.min(minY, s.y); maxY = Math.max(maxY, s.y); }
    return { x0, x: s.x, z: s.z, minY, maxY, gate: [...D.net.closed], g: t.ground(s.x, s.z, s.y) };
  });
  log('(c) cầu đóng, lái qua', C3);
  out.c3 = C3;
  await frames(P, 2);
  await P.screenshot({ path: SCREENS + 'drive-swing-closed.png' });
  out.errors = errors;
  log('lỗi trang', errors);
} catch (e) {
  console.error('LỖI SCRIPT', e);
} finally {
  console.log('KET-QUA', JSON.stringify(out));
  await browser.close(); srv.close();
}

